def transform(grid):
    # Identify each disconnected nonzero shape; return the largest connected component's tight crop.
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(y+dy,x+dx)
                        if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
                            seen.add(q); stack.append(q)
                comps.append(cells)
    # Main shape is the one with greatest extent/area, output its crop.
    cells=max(comps,key=len)
    a,b=min(y for y,x in cells),min(x for y,x in cells); z,t=max(y for y,x in cells),max(x for y,x in cells)
    return [[grid[y][x] for x in range(b,t+1)] for y in range(a,z+1)]
